async function client(){for(let i=0;i<40;i++){const c=window.screenings4uSupabase||window.supabaseClient;if(c?.auth?.getSession)return c;await new Promise(r=>setTimeout(r,50))}throw new Error('Supabase client unavailable.');}
async function call(action,extra={}){const c=await client(),{data:{session}}=await c.auth.getSession();if(!session)throw new Error('Your staff session has expired.');const r=await fetch(END,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${session.access_token}`,'apikey':KEY},body:JSON.stringify({action,...extra})});const d=await r.json().catch(()=>({}));if(!r.ok||d.error)throw new Error(d.error||`Request failed (${r.status}).`);return d;}
