function opts(list,value,label){return [{value:'',label:'Select'}].concat(list.map(x=>({value:x[value],label:typeof label==='function'?label(x):x[label]})))}
function routeFor(action,id){
 if(action==='view-customer'){const [t,c]=String(id||'').split(':');return `admin-dot-customer.html?type=${encodeURIComponent(t)}&id=${encodeURIComponent(c)}`}
 if(action==='edit-ctpa')return `admin-dot-customer.html?type=ctpa&id=${encodeURIComponent(id)}#company`;
 if(action==='edit-employer')return `admin-dot-customer.html?type=employer&id=${encodeURIComponent(id)}#company`;
 if(action==='edit-owner')return `admin-dot-customer.html?type=owner_operator&id=${encodeURIComponent(id)}#company`;
 if(action==='ctpa-access')return `admin-dot-customer.html?type=ctpa&id=${encodeURIComponent(id)}#access`;
 if(action==='ctpa-pricing')return `admin-dot-ctpa-pricing.html?ctpa_id=${encodeURIComponent(id)}`;
 if(action==='ctpa-message')return `admin-dot-customer.html?type=ctpa&id=${encodeURIComponent(id)}#message`;
 if(action==='membership-status')return `admin-dot-portal-user.html?id=${encodeURIComponent(id)}`;
 if(action==='edit-driver'||action==='driver-portal')return `admin-dot-record.html?resource=driver&id=${encodeURIComponent(id)}`;
 if(action==='edit-program')return `admin-dot-record.html?resource=program&id=${encodeURIComponent(id)}`;
 if(action==='edit-pool')return `admin-dot-record.html?resource=pool&id=${encodeURIComponent(id)}`;
 if(action==='edit-clearinghouse')return `admin-dot-record.html?resource=clearinghouse&id=${encodeURIComponent(id)}`;
 if(action==='edit-regulatory')return `admin-dot-record.html?resource=regulatory&id=${encodeURIComponent(id)}`;
 if(action==='edit-case')return `admin-dot-record.html?resource=compliance&id=${encodeURIComponent(id)}`;
 if(action==='edit-sap')return `admin-dot-record.html?resource=sap&id=${encodeURIComponent(id)}`;
 if(action==='remove-member')return `admin-dot-record.html?resource=pool_member&id=${encodeURIComponent(id)}`;
 if(action==='selection-workflow')return `admin-dot-record.html?resource=selection&id=${encodeURIComponent(id)}`;
 if(action==='configure-service')return `admin-dot-record.html?resource=service&id=${encodeURIComponent(id)}`;
 if(action==='open-document'||action==='archive-document')return `admin-dot-record.html?resource=document&id=${encodeURIComponent(id)}`;
 return '';
}
function rowButton(label,action,id){const href=routeFor(action,id);return href?`<a class="ep-business-btn ep-row-link" href="${esc(href)}">${esc(label)}</a>`:''}
const actionGroup=(...items)=>`<div class="ep-row-actions">${items.filter(Boolean).join('')}</div>`
