if(action==='drivers')r=(d.drivers||[]).map(x=>[[x.first_name,x.last_name].filter(Boolean).join(' '),empName(x.employer_id),`${x.dot_agency||'—'}${x.cdl_number?' · '+x.cdl_number:''}`,badge(x.employment_status),rowButton('Manage Driver','edit-driver',x.id)]);
