if(action==='programs')r=(d.programs||[]).map(x=>[x.name,empName(x.employer_id),x.dot_agency||'—',badge(x.status),rowButton('Manage','edit-program',x.id)]);
if(action==='pools')r=(d.pools||[]).filter(x=>page!=='admin-dot-consortiums.html'||x.pool_type==='consortium').map(x=>[x.name,x.pool_type==='consortium'?ctpaName(x.ctpa_id):empName(x.employer_id),x.dot_agency||'—',badge(x.status),rowButton('Manage','edit-pool',x.id)]);
