if(action==='selections')r=(d.selections||[]).map(x=>[poolName(x.pool_id),fmt(x.selection_date),x.population_size,badge(x.status),rowButton('Manage','selection-workflow',x.id)]);
if(action==='clearinghouse')r=(d.clearinghouse||[]).map(x=>[ctpaName(x.ctpa_id),x.clearinghouse_account_name||x.registered_email||'—',[x.query_management_enabled?'Queries':null,x.violation_management_enabled?'Violations':null,x.rtd_management_enabled?'RTD':null].filter(Boolean).join(', ')||'—',badge(x.setup_status),rowButton('Manage','edit-clearinghouse',x.id)]);
if(action==='new_entrant')r=(d.regulatory||[]).map(x=>[empName(x.employer_id),x.agency_code,x.account_identifier||'—',badge(x.status),rowButton('Manage','edit-regulatory',x.id)]);
if(action==='rtd')r=(d.rtd_cases||[]).map(x=>[x.compliance_case_id,fmt(x.evaluation_date),x.return_to_duty_status||'—',badge(x.status),rowButton('Manage','edit-sap',x.id)]);
if(action==='compliance')r=(d.compliance_cases||[]).map(x=>[x.case_number,empName(x.employer_id),x.priority,badge(x.status),rowButton('Manage','edit-case',x.id)]);
